#include "PhysicsWorld.h"
#include <cstdio>
#include <cmath>
int main(){for(float e:{0.f,.2f,.5f,1.f})for(float speed:{1.f,5.f,20.f,100.f})for(float spin:{0.f,5.f,20.f,100.f}){PhysicsWorld w;w.Init();w.CreateStaticBox({.6f,0,0},{.05f,1,1},0,e);w.CreateStaticBox({-.6f,0,0},{.05f,1,1},0,e);auto b=w.CreateDynamicBox({0,0,0},{.08f,.2f,.05f},1,0,e);w.SetLinearVelocity(b,{speed,0,0});w.SetAngularVelocity(b,{0,0,spin});auto energy=[&](){glm::dvec3 v(w.GetLinearVelocity(b)),om(w.GetAngularVelocity(b));return .5*glm::dot(v,v)+.5*glm::dot(om,glm::dmat3(w.GetInertiaWorld(b))*om);};double before=energy(),peak=before;size_t events=0,holds=0;int completed=0;try{for(;completed<120;++completed){w.Step(1.f/60);peak=std::max(peak,energy());events+=w.LastStepStats().impactEvents;holds+=w.LastStepStats().impactSafetyFallback;}}catch(const std::exception& err){printf("ERROR %s ",err.what());}printf("e%g speed%g spin%g steps%d before%.9g peak%.9g final%.9g ratio%.9g events%zu holds%zu\n",e,speed,spin,completed,before,peak,energy(),peak/before,events,holds);fflush(stdout);}}
